import {useCallback,useEffect,useState} from 'react'; import {getDetails} from '../api/tmdbApi';
const useFetchDetails=endpoint=>{const[data,setData]=useState();const[loading,setLoading]=useState(false);const[error,setError]=useState(null);const[version,setVersion]=useState(0);const retry=useCallback(()=>setVersion(value=>value+1),[]);useEffect(()=>{const controller=new AbortController();const fetchData=async()=>{try{setLoading(true);setError(null);const response=await getDetails(endpoint,{signal:controller.signal});setData(response.data);}catch(requestError){if(requestError.code!=='ERR_CANCELED'){setError(requestError);setData(undefined);}}finally{if(!controller.signal.aborted)setLoading(false);}};if(endpoint)fetchData();return()=>controller.abort();},[endpoint,version]);return{data,loading,error,retry};}; export default useFetchDetails;
